export const getListOutboxUrl = () => {




  return `/api/admin/outbox`
}

/**
 * @summary List recent email outbox items
 */
export const listOutbox = async ( options?: Parameters<typeof customFetch>[1]): Promise<OutboxItem[]> => {

  return customFetch<OutboxItem[]>(getListOutboxUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListOutboxQueryKey = () => {
    return [
    `/api/admin/outbox`
    ] as const;
    }


export const getListOutboxQueryOptions = <TData = Awaited<ReturnType<typeof listOutbox>>, TError = ErrorType<void>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listOutbox>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListOutboxQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listOutbox>>> = ({ signal }) => listOutbox({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listOutbox>>, TError, TData> & { queryKey: QueryKey }
}

export type ListOutboxQueryResult = NonNullable<Awaited<ReturnType<typeof listOutbox>>>
export type ListOutboxQueryError = ErrorType<void>


/**
 * @summary List recent email outbox items
 */

export function useListOutbox<TData = Awaited<ReturnType<typeof listOutbox>>, TError = ErrorType<void>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listOutbox>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getListOutboxQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







